mapper.select:
select hd.*, hpl.description, hd.sheet_name, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'PRICE.CONFIG_TYPE' and s.code_value = hd.config_type)config_type_n from hls_price_list_config_hd hd left join hls_price_list hpl on hpl.price_list = hd.price_list
AND hd.price_list=#{priceList}
AND hd.table_type=#{tableType}
and hd.sheet_name = #{sheetName}
and (hd.config_type is null or hd.config_type = 'OUTPUT')
